package app.masroufy.core

/** بنك النصايح الموثّقة — الجزء 3 من 3 (متولّد بـ`gen-tips.js`؛ شوف [VERIFIED_TIPS]). بيانات بس. */
internal val VERIFIED_TIPS_3: List<BankTip> = listOf(
    BankTip(
        "gosi-pension-check-before-retiring", "sa", "none", TipGroup.START,
        sa = TipWords("راجع سجلك في التأمينات الاجتماعية قبل ترك العمل", "قبل ترك العمل، تحقق من عدد أشهر اشتراكك لدى المؤسسة العامة للتأمينات الاجتماعية. يُشترط للمعاش التقاعدي بلوغ سن 60 وترك العمل الخاضع للنظام، مع 120 شهر اشتراك على الأقل، ويتطلب التقاعد المبكر قبل الستين 300 شهر. وإن نقصت مدتك عن 120 شهرًا فاستفسر عن ضم مدة اعتبارية تُسدَّد بنسبة 18% دفعة واحدة أو بالتقسيط. وبعد التقاعد احرص على تقديم الإقرار السنوي في موعده وتجديد الوكالة، إذ إن غياب الإقرار أو مضي أكثر من ثلاث سنوات على الوكالة من أسباب إيقاف صرف المعاش.", "التقاعد قبل استيفاء شروط الاشتراك قد يُفقد صاحبه أشهرًا أو سنوات من معاشه، وقد يتوقف الصرف بسبب إجراء ورقي بسيط."),
        eg = TipWords("راجع ملفك في التأمينات قبل ما تسيب الشغل", "قبل ما تسيب شغلك، اتأكد من عدد شهور اشتراكك في التأمينات الاجتماعية. المعاش العادي محتاج سن 60، وإنك تكون سبت العمل المشمول بالنظام، و120 شهر اشتراك على الأقل. والتقاعد المبكر قبل 60 محتاج 300 شهر. لو ناقصك عن الـ120 شهر، اسأل المؤسسة عن ضم مدة اعتبارية بتتدفع بنسبة 18% مرة واحدة أو على أقساط. وبعد التقاعد، ابعت الإقرار السنوي في ميعاده وجدّد أي وكالة، لأن غياب الإقرار أو وكالة عدّى عليها أكتر من 3 سنين من أشهر أسباب وقف صرف المعاش.", "لو طلعت معاش قبل ما تكمّل الشروط ممكن تخسر شهور أو سنين من معاشك، ولو نسيت ورقة بسيطة ممكن الصرف يقف."),
        source = TipSource("المؤسسة العامة للتأمينات الاجتماعية: الأسئلة الشائعة للمتقاعدين", "https://www.gosi.gov.sa/GOSIOnline/FAQ_Retired&locale=en_US", "2026-10-16"),
    ),
    BankTip(
        "nosi-file-check-before-pension", "eg", "none", TipGroup.START,
        sa = TipWords("راجع ملفك في التأمينات الاجتماعية بمصر قبل طلب المعاش", "قبل التقاعد بوقت كافٍ، راجع مكتب التأمينات التابع لك وتأكد أن صاحب العمل سجّلك فعلًا، فإن لم تكن مسجلًا فيمكنك التقدم بالاستمارة رقم 1. واعرف المدد المحتسبة؛ فمدة الخدمة العامة مثلًا لا تُحتسب ضمن مدد الاشتراك. وإذا بلغت الستين دون استكمال المدة المطلوبة، يمكنك الاستمرار في العمل والتأمين حتى تستكملها. وعند تقديم طلب المعاش حدِّد موقفك من التأمين الصحي، لأن صاحب المعاش لا يحصل عليه إلا إذا طلبه في طلب المعاش، مقابل خصم 1% من المعاش.", "اكتشاف عدم التسجيل أو وجود مدد غير محتسبة أو إغفال اختيار التأمين الصحي في يوم تقديم الطلب أمر مكلف."),
        eg = TipWords("راجع ملف التأمينات بتاعك قبل ما تقدّم على المعاش", "قبل المعاش بوقت كفاية، روح مكتب التأمينات التابع ليك واتأكد إن صاحب الشغل سجّلك فعلًا. لو مش متسجّل، تقدر تقدّم استمارة 1. واعرف المدد اللي بتتحسب: مدة الخدمة العامة مثلًا مش بتتحسب مدة اشتراك. ولو وصلت 60 سنة ومدتك ناقصة، تقدر تكمّل شغل وتفضل مؤمَّن عليك لحد ما تكمّلها. ولما تقدّم على المعاش، قرّر ساعتها موضوع التأمين الصحي، لأن صاحب المعاش بياخده بس لو طلبه في طلب المعاش، مقابل خصم 1% من المعاش.", "إنك تكتشف يوم التقديم إنك مش متسجّل، أو إن في مدد مش محسوبة، أو إنك نسيت تختار التأمين الصحي، حاجة بتكلّف كتير."),
        source = TipSource("الهيئة القومية للتأمين الاجتماعي في مصر: الأسئلة الشائعة", "https://www.nosi.gov.eg/ar/About/Pages/FAQ.aspx", "2026-10-16"),
    ),
    BankTip(
        "lump-sum-no-rush", "both", "none", TipGroup.START,
        sa = TipWords("لا تتعجل في قرار المبلغ المقطوع", "إذا حصلت عند التقاعد على مبلغ كبير دفعة واحدة، كمكافأة نهاية الخدمة أو تعويض مقطوع، فلا تتعجل في تقرير طريقة استخدامه. امنح نفسك وقتًا كافيًا، كعدة أشهر، لفهم الخيارات المتاحة. وقبل استثمار أي جزء منه، سدِّد الديون مرتفعة التكلفة، وتحقق من أن العرض المقدَّم ليس احتيالًا.", "وصول مبلغ كبير دفعة واحدة يُغري بالإنفاق المتسرع ويجذب ضغط المسوّقين والمحتالين، وسداد الدين المكلف توفير مؤكد لا يستطيع أي استثمار أن يعد بمثله."),
        eg = TipWords("ما تستعجلش في قرار المبلغ الكبير", "لو جالك مبلغ كبير مرة واحدة وانت بتطلع معاش، زي مكافأة نهاية الخدمة أو تعويض مقطوع، ما تقررش بسرعة هتعمل بيه إيه. ادّي نفسك وقت، كام شهر مثلًا، عشان تفهم الاختيارات اللي قدامك. وقبل ما تستثمر أي جزء منه، سدّ الديون الغالية الأول، واتأكد إن العرض اللي قدامك مش نصب.", "المبلغ الكبير لما ييجي مرة واحدة بيشدّ الصرف السريع وضغط البيّاعين والنصابين. وسداد الدين الغالي توفير أكيد، وده حاجة مفيش استثمار يقدر يوعدك بيها."),
        source = TipSource("موقع توعية المستثمرين التابع لهيئة الأوراق المالية والبورصات الأمريكية: إدارة الدخل مدى الحياة", "https://www.investor.gov/additional-resources/retirement-toolkit/managing-lifetime-income", "2026-10-16"),
    ),
    BankTip(
        "retiree-fraud-target", "both", "high", TipGroup.PROTECT,
        sa = TipWords("المتقاعدون هدف مفضّل للاحتيال", "كثيرًا ما يستهدف المحتالون المقبلين على التقاعد والمتقاعدين، مستغلين خوفهم من نفاد المال أو من تكاليف العلاج. خذ وقتك ولا تسمح لأحد باستعجالك. واحذر العروض التي تصلك دون طلب، وكل ما يُقدَّم على أنه «فرصة العمر» أو يبدو أجمل من أن يكون حقيقيًا. وتحقق من البائع حتى لو كانت بينكما معرفة شخصية، وإن تعذّر عليك سحب أموالك فذلك مدعاة للريبة.", "مدخرات التقاعد والمبالغ المقطوعة كبيرة ويصعب تعويضها، وقد تمحو عملية احتيال واحدة ادخار سنوات."),
        eg = TipWords("اللي على المعاش هدف مفضّل للنصابين", "النصابين كتير بيستهدفوا اللي قرّبوا على المعاش أو طلعوا فعلًا، وبيلعبوا على خوفهم إن الفلوس تخلص أو من مصاريف العلاج. خد وقتك وما تسيبش حد يستعجلك. خلي بالك من أي عرض جالك من غير ما تطلبه، ومن أي حاجة بيقولوا عليها «فرصة العمر» أو أحلى من إنها تكون حقيقية. اسأل عن البيّاع واتأكد منه حتى لو تعرفه شخصيًا. ولو مش قادر تسحب فلوسك، يبقى في حاجة غلط.", "مدخرات المعاش والمبالغ الكبيرة صعب تتعوض، ونصباية واحدة ممكن تضيّع شقا سنين."),
        source = TipSource("موقع توعية المستثمرين التابع لهيئة الأوراق المالية والبورصات الأمريكية: تجنّب الاحتيال عند التقاعد", "https://www.investor.gov/additional-resources/retirement-toolkit/avoiding-retirement-fraud", "2026-10-16"),
    ),
    BankTip(
        "small-regular-amounts-over-time", "both", "medium", TipGroup.START,
        sa = TipWords("المبالغ الصغيرة المنتظمة مع الوقت خير من انتظار مبلغ كبير", "لا تحتاج إلى راتب كبير لتبدأ. فبعد تكوين صندوق الطوارئ والتخلص من الديون المكلفة، خصِّص مبلغًا صغيرًا ثابتًا كل شهر لأهدافك البعيدة. والبدء في سن مبكرة يمنح المال وقتًا أطول قد ينمو فيه، وتوزيعه على شركات كثيرة، عبر صندوق متنوع مثلًا، يحدّ من الضرر إن تراجعت إحداها. وتذكَّر أن الاستثمار، بخلاف المال المودَع في البنك، قد تنخفض قيمته.", "الوقت أكبر ميزة لدى الشباب، والمبالغ الصغيرة المنتظمة تتراكم."),
        eg = TipWords("مبلغ صغير بانتظام مع الوقت أحسن من انتظار مبلغ كبير", "مش لازم مرتب كبير عشان تبدأ. بعد ما يبقى عندك صندوق طوارئ ومفيش عليك دين غالي، حط مبلغ صغير ثابت كل شهر لأهدافك البعيدة. لما تبدأ وانت صغير بتدّي فلوسك وقت أطول تقدر تكبر فيه. وتوزيعها على شركات كتير، مثلًا عن طريق صندوق متنوّع، بيقلل الضرر لو شركة منهم وقعت. وخلي بالك: الاستثمار، عكس الفلوس اللي في البنك، ممكن قيمته تنزل.", "الوقت هو أكبر ميزة عند الشاب، والمبالغ الصغيرة المنتظمة بتتجمع."),
        source = TipSource("موقع توعية المستثمرين التابع لهيئة الأوراق المالية والبورصات الأمريكية: بناء الثروة، خريطة طريق للطلاب", "https://www.investor.gov/building-wealth-roadmap-student", "2026-10-16"),
    ),
    BankTip(
        "check-finfluencers", "both", "none", TipGroup.PROTECT,
        sa = TipWords("تحقَّق ممن يقف وراء النصائح المالية على مواقع التواصل", "قبل العمل بنصيحة استثمارية من أحد المؤثرين، تحقق من أنه مرخَّص لتقديم المشورة المالية، واسأل نفسك هل يتقاضى أجرًا على الترويج لما يوصي به، وعُدَّ أي وعد بربح سريع أو مضمون علامة خطر. ولا تعتمد على كلام مؤثر واحد، بل قارنه بمصادر رسمية أو مرخَّصة.", "يستقي الطلاب كثيرًا من معلوماتهم المالية من مواقع التواصل، حيث تنتشر النصائح غير المرخَّصة والترويج المدفوع."),
        eg = TipWords("اعرف مين ورا نصايح الفلوس على مواقع التواصل", "قبل ما تمشي ورا نصيحة استثمار من مؤثّر، اتأكد إنه مرخّص يدّي نصايح مالية، واسأل نفسك هل بياخد فلوس عشان يروّج للي بينصح بيه، واعتبر أي وعد بربح سريع أو مضمون علامة خطر. وما تعتمدش على كلام مؤثّر واحد، قارنه بمصادر رسمية أو مرخّصة.", "الطلبة بياخدوا معظم معلوماتهم عن الفلوس من مواقع التواصل، وهناك النصايح من غير ترخيص والإعلانات المدفوعة منتشرة."),
        source = TipSource("المنظمة الدولية لهيئات الأوراق المالية: التقرير النهائي عن المؤثرين الماليين (مايو 2025)", "https://www.iosco.org/library/pubdocs/pdf/IOSCOPD795.pdf", "2026-10-16"),
    ),
    BankTip(
        "halal-stock-two-step-check", "both", "medium", TipGroup.HALAL,
        sa = TipWords("فحص شرعية السهم على خطوتين", "ابدأ بنشاط الشركة الرئيس: تُستبعد البنوك والتأمين التقليديان والخمور والقمار ولحم الخنزير والتبغ. ثم انظر في قوائمها المالية: وفق المعيار الشرعي رقم 21 لهيئة المحاسبة والمراجعة للمؤسسات المالية الإسلامية تبقى الديون الربوية دون 30%، والنقد والاستثمارات ذات الفائدة دون 30%، والدخل من الأنشطة غير المباحة دون 5% من إجمالي الدخل.", "قد تبيع الشركة منتجات مباحة وهي ممولة بقروض ربوية كبيرة، وفحص النسب يكشف ذلك. وتعتمد بعض جهات المؤشرات حدودًا مختلفة قليلًا كـ33%. ولأن أرقام الشركة تتغير مع كل تقرير فقد تتغير حالة السهم، فيلزم إعادة فحصه دوريًا."),
        eg = TipWords("اعرف السهم حلال ولا لأ في خطوتين", "الأول بص على نشاط الشركة الأساسي: البنوك والتأمين التقليدي والخمور والقمار والخنزير والدخان مستبعدين. بعدين بص على أرقامها: حسب المعيار الشرعي رقم 21 لهيئة المحاسبة والمراجعة للمؤسسات المالية الإسلامية، الديون بفايدة لازم تفضل أقل من 30%، والكاش والاستثمارات اللي بفايدة كمان أقل من 30%، والدخل من نشاط غير مباح أقل من 5% من إجمالي الدخل.", "الشركة ممكن تبيع حاجة حلال وتكون ممولة بقروض بفايدة كتير، والنسب دي بتكشف ده. بعض مزودي المؤشرات بيستخدموا حدود مختلفة شوية زي 33%. وأرقام الشركة بتتغير مع كل تقرير، فحالة السهم ممكن تتغير وتحتاج تراجعها كل فترة."),
        source = TipSource("هيئة المحاسبة والمراجعة للمؤسسات المالية الإسلامية: منهجية الفحص الشرعي، عرض الأمين العام في منتدى بورصات الدول الأعضاء بمنظمة التعاون الإسلامي (2017)", "https://oicexchanges.org/files/1---shari-ah-screening-in-the-islamic-capital-markets-dr-hamed-merah-secretary-general-aaoifi.pdf", "2026-10-16"),
    ),
    BankTip(
        "purify-mixed-stock-income", "both", "none", TipGroup.HALAL,
        sa = TipWords("تطهير الجزء غير المباح من الأرباح", "إذا امتلكت سهمًا «مختلطًا» نشاطه الرئيس مباح وله دخل يسير من نشاط غير مباح، فاحسب حصة هذا الجزء من توزيعاتك وتصدّق بها، ولا تعدّها من ربحك.", "يُجاز الاستثمار في الشركات المختلطة بشرط التطهير، وإن أهملته بقي ذلك الجزء ضمن مكاسبك."),
        eg = TipWords("طهّر الجزء الصغير غير الحلال من أرباحك", "لو معاك سهم «مختلط»، يعني نشاطه الأساسي حلال بس عنده دخل صغير من نشاط غير مباح، احسب نصيب الجزء ده من توزيعاتك واتبرع بيه، وما تحسبوش من ربحك.", "الاستثمار في الشركات المختلطة مسموح بشرط التطهير، ولو ما طهّرتش الجزء ده بيفضل جوه مكسبك."),
        source = TipSource("هيئة المحاسبة والمراجعة للمؤسسات المالية الإسلامية: منهجية الفحص الشرعي، عرض الأمين العام في منتدى بورصات الدول الأعضاء بمنظمة التعاون الإسلامي (2017)", "https://oicexchanges.org/files/1---shari-ah-screening-in-the-islamic-capital-markets-dr-hamed-merah-secretary-general-aaoifi.pdf", "2026-10-16"),
    ),
    BankTip(
        "sukuk-not-bonds", "both", "medium", TipGroup.HALAL,
        sa = TipWords("الصكوك ليست سندات، وليست خالية من المخاطر", "السندات التقليدية تدفع فائدة فلا تناسب، أما الصكوك فهي البديل الشرعي لأن حاملها يملك حصة في أصول حقيقية أو منافعها. وهذه الملكية تعني تحمّل المخاطر أيضًا: فلا يضمن المدير رأس المال أو ربحًا ثابتًا، وتُوزَّع الخسارة بحسب ملكية كل حامل.", "يعامل كثيرون الصكوك كأنها ادخار مضمون، ومعرفتك بأنك تشارك في مخاطر الأصل تساعدك على تحديد ما تضعه فيها، وتذكّرك بقراءة هيكل الصك قبل الشراء."),
        eg = TipWords("الصكوك مش سندات، ومش من غير مخاطرة", "السندات التقليدية بتدفع فايدة ومش مناسبة. الصكوك هي البديل الشرعي لأن صاحبها بيملك حصة في أصول حقيقية أو منفعتها. والملكية دي معناها مخاطرة كمان: المدير ما ينفعش يضمن رأس مالك أو ربح ثابت، والخسارة بتتوزع على قد ملكية كل واحد.", "ناس كتير بتتعامل مع الصكوك كأنها ادخار مضمون. لما تعرف إنك شريك في مخاطرة الأصل هتقدر تحدد تحط فيها قد إيه، وهتفتكر تقرا هيكل الصك قبل ما تشتري."),
        source = TipSource("مجمع الفقه الإسلامي الدولي: القرار رقم 178 (4/19) بشأن الصكوك الإسلامية (2009)", "https://iifa-aifi.org/en/32984.html", "2026-10-16"),
    ),
    BankTip(
        "small-fees-add-up", "both", "low", TipGroup.SPREAD,
        sa = TipWords("الرسوم الصغيرة تتراكم مع السنين", "قبل الاستثمار، قارن إجمالي الرسوم السنوية للصندوق وتكاليف الشراء والبيع؛ ففارق يبدو ضئيلًا مثل 0.25% مقابل 1% سنويًا قد يُنقص النتيجة بوضوح على مدى عشرين عامًا.", "تُدفع الرسوم كل عام سواء أحسن الصندوق أم أساء، ويتعاظم أثرها بمرور الوقت."),
        eg = TipWords("الرسوم الصغيرة بتكبر مع السنين", "قبل ما تستثمر، قارن إجمالي الرسوم السنوية للصندوق وتكاليف البيع والشرا. فرق شكله صغير، زي 0.25% قصاد 1% في السنة، ممكن يقلل النتيجة بشكل واضح على عشرين سنة.", "الرسوم بتدفعها كل سنة سواء الصندوق كسب أو خسر، وتأثيرها بيكبر مع الوقت."),
